from src.knapsack import knapsack

def test_basic():
    # weights [1,3,4,5], values [1,4,5,7], capacity 7 -> 9 (items 1+3 or 0+2)
    assert knapsack(7, [1, 3, 4, 5], [1, 4, 5, 7]) == 9

def test_single_item_fits():
    assert knapsack(10, [5], [42]) == 42

def test_single_item_too_heavy():
    assert knapsack(4, [5], [42]) == 0

def test_zero_capacity():
    assert knapsack(0, [1, 2], [10, 20]) == 0

def test_all_items_fit():
    assert knapsack(100, [1, 2, 3], [10, 20, 30]) == 60
